// Generated by `just generate` from `src/kernel/repo/orgs.ts`. Edit the source and run `just generate`.
// The GitHub organizations that the user owns, read from the output of `gh api --paginate --slurp user/memberships/orgs?state=active`.
// The GitHub REST docs give the role `admin` to an owner of an organization, so only that role counts.
// The reading is structural: it reads the JSON fields `state`, `role`, and `organization.login`.
// The `policy` and `setup` slices read it from here, because a slice imports only `src/kernel/` and its own folder.

/** The logins of the organizations that the user owns, in lower case, or `undefined` when `text` is not the JSON of the endpoint. */
export const ownedOrgsOf = (text: string): string[] | undefined => {
  let pages: unknown;
  try {
    pages = JSON.parse(text);
  } catch {
    return undefined;
  }
  if (!Array.isArray(pages)) return undefined;
  const out: string[] = [];
  for (const m of pages.flat()) {
    const row = m as {
      state?: unknown;
      role?: unknown;
      organization?: { login?: unknown };
    } | null;
    const login = row?.organization?.login;
    if (
      row?.state === "active" &&
      row.role === "admin" &&
      typeof login === "string" &&
      login !== ""
    )
      out.push(login.toLowerCase());
  }
  return out;
};
